using namespace boost::ut;using namespace folia::math;using namespace folia::math::mml;
struct HookAccess{virtual ~HookAccess()=default;virtual void callHook(AttributeList,Property,Property,Property)=0;};
template<class T>struct Exposed:T,HookAccess{using T::T;void callHook(AttributeList a,Property d,Property l,Property p)override{T::setChildInheritedAttributes(a,d,l,p);}};
struct Leaf:Exposed<MmlMi>,TextContentBinding{using Exposed<MmlMi>::Exposed;std::function<void(AttributeList,Property,Property,Property)> after;protected:void inheritAttributes(AttributeList a,Property d,Property l,Property p)override{MmlMi::inheritAttributes(a,d,l,p);if(after)after(a,d,l,p);}};
struct Text:TextNode{using TextNode::TextNode;std::function<void()> after,afterInheritance;protected:void inheritAttributes(AttributeList a,Property d,Property l,Property p)override{AbstractMmlEmptyNode::inheritAttributes(a,d,l,p);if(afterInheritance)afterInheritance();}public:std::u16string getText()const override{auto v=TextNode::getText();if(after)after();return v;}};
struct Probe:Exposed<AbstractMmlNode>{using Exposed<AbstractMmlNode>::Exposed;double value=std::numeric_limits<double>::infinity();std::string kind()const override{return "probe";}double arity()const override{return value;}bool linebreakContainer()const override{return true;}std::string linebreakAlign()const override{return "indentalign";}};
struct Observed:MmlFactory{std::vector<MmlNode*> nodes;Observed(){setNodeClass("mi",classBinding<Leaf>());setNodeClass("text",classBinding<Text>());setNodeClass("mrow",classBinding<Exposed<MmlMrow>>());setNodeClass("mfrac",classBinding<Exposed<MmlMfrac>>());setNodeClass("msubsup",classBinding<Exposed<MmlMsubsup>>());setNodeClass("probe",classBinding<Probe>());}MmlNode* create(std::string_view k,tree::FactoryArgs args)override{auto*n=MmlFactory::create(k,args);if(std::find(nodes.begin(),nodes.end(),n)==nodes.end())nodes.push_back(n);return n;}std::string tag(NodeValue v)const{if(v.kind()==tree::ChildKind::Undefined)return "U";if(v.kind()==tree::ChildKind::Null)return "N";auto p=std::find(nodes.begin(),nodes.end(),v.nodeOrNull());return p==nodes.end()?"UNBOUND":"n"+std::to_string(p-nodes.begin());}};
struct Case{std::string op,kind,shape,mode,prototype;int args,attrs,arity;bool explicitAttrs,arrayNull,attributesNull,noncallable;std::string expected;};
std::string units(std::u16string_view s){std::string v;for(auto c:s){if(!v.empty())v+='.';v+=std::to_string(c);}return v;}
std::string scalar(const Property& p){if(p.missing())return "U";if(std::holds_alternative<PropertyNull>(p.value))return "N";if(auto b=std::get_if<bool>(&p.value))return *b?"T":"F";if(auto n=std::get_if<double>(&p.value))return "D"+(*n==0&&std::signbit(*n)?std::string("-0"):host::debugText(host::string(p)));if(auto s=std::get_if<std::string>(&p.value))return "S"+units(host::text(*s));if(auto a=PropertyArray::array(p)){std::string out="A[";for(std::size_t i=0;i<a->size();++i){if(i)out+=',';out+=scalar(a->get(i));}return out+']';}if(auto o=PropertyList::object(p)){std::string out="P{";for(const auto& k:o->keys()){if(out!="P{")out+=',';out+=k+'='+scalar(o->get(k));}return out+'}';}return "UNBOUND";}
std::string ascii(std::u16string_view s){std::string v;for(auto c:s)v+=static_cast<char>(c);return v;}
std::array<Property,4> arguments(int mode){if(mode==0)return {PropertyList{},false,0,false};if(mode==1)return {Missing{},Missing{},Missing{},Missing{}};if(mode==2)return {PropertyList{},PropertyNull{},"2","x"};return {PropertyList{},true,2,true};}
Property inputAttrs(int mode){if(mode==1)return PropertyList{{"mathcolor",attributeTuple("mstyle","blue")},{"unknown",attributeTuple("mstyle",7)}};if(mode==2)return PropertyList{{"mathvariant",attributeTuple("mstyle","bold")},{"displaystyle",attributeTuple("mstyle",true)},{"scriptlevel",attributeTuple("mstyle",3)}};if(mode==3)return PropertyNull{};if(mode==5)return PropertyList{{"mathcolor",attributeTuple("mstyle","red")},{"force",attributeTuple("mstyle",9)},{"unknown",attributeTuple("mstyle",7)}};return Missing{};}
struct Restore{PropertyList no=AbstractMmlNode::noInherit(),stop=AbstractMmlNode::stopInherit(),always=AbstractMmlNode::alwaysInherit();~Restore(){AbstractMmlNode::noInherit()=no;AbstractMmlNode::stopInherit()=stop;AbstractMmlNode::alwaysInherit()=always;}};
std::string run(const Case& c){Restore restore;if(c.kind=="probe"){auto no=host::objectAssign(restore.no),style=host::objectAssign(restore.no.get("mstyle"));style.set("probe",PropertyList{{"mathcolor",true}});no.set("mstyle",style);AbstractMmlNode::noInherit()=no;auto stop=host::objectAssign(restore.stop);stop.set("probe",PropertyList{{"force",true}});AbstractMmlNode::stopInherit()=stop;auto always=host::objectAssign(restore.always);always.set("force",true);AbstractMmlNode::alwaysInherit()=always;}
 Observed f;std::map<char,MmlNode*> nodes;for(char label:{'a','b','c'})nodes[label]=f.create(std::string_view("mi"),tree::FactoryArgs{});for(const auto&[label,text]:std::array<std::pair<char,std::u16string_view>,3>{{{'t',u"x"},{'e',u"\U0001F600"},{'f',u"\u0301"}}}){nodes[label]=f.create(std::string_view("text"),tree::FactoryArgs{});dynamic_cast<Text*>(nodes[label])->setText(std::u16string(text));}nodes['r']=f.create(std::string_view("mi"),tree::FactoryArgs{});auto*rich=dynamic_cast<Leaf*>(nodes['r']);if(c.noncallable)rich->textContent=std::function<std::u16string()>{};else rich->textContent=[] {return std::u16string(u"R");};auto*node=f.create(std::string_view(c.kind),tree::FactoryArgs{});if(c.kind=="probe")dynamic_cast<Probe*>(node)->value=c.arity==255?std::numeric_limits<double>::infinity():c.arity;
 const auto shape=[&](std::string_view s){auto a=std::make_shared<tree::ChildArray<MmlNode>>();a->resize(s.size());for(std::size_t p=0;p<s.size();++p)if(s[p]!='H')a->set(p,s[p]=='U'?NodeValue(Missing{}):s[p]=='N'?NodeValue(PropertyNull{}):NodeValue(nodes.at(s[p])));return a;};node->childNodes=c.arrayNull?Children{}:shape(c.shape);const auto original=node->childNodes;if(!c.prototype.empty())original->setPrototype(shape(c.prototype));if(c.attributesNull)node->setAttributes(nullptr);if(c.explicitAttrs){node->attributes()->set("displaystyle",PropertyNull{});node->attributes()->set("scriptlevel","3");node->attributes()->set("indentalign","right");}
 std::vector<std::string> trace;const auto action=[&]{if(c.mode=="append")original->push_back(nodes[c.op=="text"?'e':'b']);if(c.mode=="delete")original->erase(1);if(c.mode=="shrink")original->resize(1);if(c.mode=="rebind")node->childNodes=shape("c");if(c.mode=="throw")throw Error("Error",u"boom");};dynamic_cast<Leaf*>(nodes['a'])->after=[&](AttributeList a,Property d,Property l,Property p){trace.push_back("inherit:a:"+scalar(a)+':'+scalar(d)+':'+scalar(l)+':'+scalar(p));action();};dynamic_cast<Text*>(nodes['t'])->after=[&]{trace.push_back("text:t");action();};
 if(c.mode=="skipProbe")dynamic_cast<Text*>(nodes['t'])->afterInheritance=[&]{trace.push_back("text:inherit");};
 auto v=arguments(c.args);if(c.attrs!=0)v[0]=inputAttrs(c.attrs);const auto incoming=v[0];std::string result="THREW",error="ok";try{if(c.op=="text")result="S"+units(dynamic_cast<AbstractMmlTokenNode*>(node)->getText());else{if(c.op=="hook")dynamic_cast<HookAccess*>(node)->callHook(v[0],v[1],v[2],v[3]);else node->setInheritedAttributes(v[0],v[1],v[2],v[3]);result="U";}}catch(const Error&e){error=e.name+'|'+ascii(e.message);}
 const auto snap=[&](const Children&a){if(!a)return std::string("N");std::string own,has,values;for(std::size_t p=0;p<a->size();++p){own+=a->hasOwn(p)?'1':'0';has+=a->has(p)?'1':'0';if(p)values+=',';values+=f.tag(a->get(p));}return std::to_string(a->size())+':'+own+':'+has+':'+values;};std::string out=error+'|'+result+'|';for(std::size_t n=0;n<f.nodes.size();++n){if(n)out+=';';auto*p=f.nodes[n];auto a=p->attributes();out+=f.tag(p)+':'+p->kind()+':'+f.tag(p->getParent())+':'+snap(p->childNodes)+':'+(a?scalar(a->getAllAttributes())+'/'+scalar(a->getAllInherited()):"N")+':'+scalar(p->getAllProperties());}out+='|'+snap(original)+'|'+(original==node->childNodes?'1':'0')+'|'+scalar(incoming)+'|';for(std::size_t n=0;n<trace.size();++n){if(n)out+=',';out+=trace[n];}return out;
}
